export interface Invoice {
  number: string;
  customer: string;
  total: number;
  currency: string;
}

export class Workbook {
  private readonly sheets: Sheet[] = [];

  addSheet(name: string): Sheet {
    const sheet = new Sheet(name);
    this.sheets.push(sheet);
    return sheet;
  }

  toBuffer(): Buffer {
    return Buffer.from(JSON.stringify(this.sheets.map((sheet) => sheet.rows)));
  }
}

class Sheet {
  readonly rows: unknown[][] = [];

  constructor(readonly name: string) {}

  appendRow(row: unknown[]): void {
    this.rows.push(row);
  }
}

export async function exportInvoices(format: string, invoices: Invoice[]): Promise<Buffer> {
  switch (format) {
    case 'csv': {
      const header = 'number,customer,total,currency';
      const rows = invoices.map((invoice) =>
        [invoice.number, invoice.customer, invoice.total, invoice.currency].join(','),
      );
      return Buffer.from([header, ...rows].join('\n'));
    }
    case 'xlsx': {
      const workbook = new Workbook();
      const sheet = workbook.addSheet('invoices');
      for (const invoice of invoices) {
        sheet.appendRow([invoice.number, invoice.customer, invoice.total]);
      }
      return workbook.toBuffer();
    }
    default:
      throw new Error(`unsupported export format: ${format}`);
  }
}

