}

export interface LedgerStore {
  markSettled(reference: string, amountCents: number): Promise<void>;
}

export function readStripeCharge(data: unknown): number {
  return (data as { amount: number }).amount;
}

export function readPaypalCapture(data: unknown): number {
  const units = (data as { purchase_units: { amount: { value: string } }[] }).purchase_units;
  return Math.round(Number(units[0]?.amount.value ?? 0) * 100);
}

export function readBraintreeTransaction(data: unknown): number {
