        const response = await this.http.get(`https://api.stripe.com/v1/charges/${settlement.reference}`);
        await this.store.markSettled(settlement.reference, readStripeCharge(response.data));
        return;
      }
      case 'paypal': {
        const response = await this.http.get(`https://api.paypal.com/v2/payments/${settlement.reference}`);
        await this.store.markSettled(settlement.reference, readPaypalCapture(response.data));
        return;
