import { Analyzer } from './analyzer';
import { VectorStore } from './vector-store';
import { TextIndex } from './text-index';
import { HybridIndex } from './hybrid-index';

export interface IndexTarget {
  type: string;
  name: string;
  documents: Document[];
}

export interface Document {
  id: string;
  body: string;
  embeddings?: number[];
}

export interface IndexClients {
  text(): TextIndex;
  vector(): VectorStore;
  hybrid(): HybridIndex;
  analyzer(): Analyzer;
}

export class IndexWriter {
  constructor(private readonly clients: IndexClients) {}

  async write(target: IndexTarget): Promise<number> {
    switch (target.type) {
      case 'text': {
        const index = this.clients.text();
        const analyzer = this.clients.analyzer();
        for (const document of target.documents) {
          index.add(document.id, analyzer.tokens(document.body));
        }
        return index.commit(target.name);
      }
      case 'vector': {
        const store = this.clients.vector();
        for (const document of target.documents) {
          if (!document.embeddings) throw new Error(`document ${document.id} has no embeddings`);
          store.upsert(target.name, document.id, document.embeddings);
        }
        return store.flush(target.name);
      }
      case 'hybrid': {
        const hybrid = this.clients.hybrid();
        const analyzer = this.clients.analyzer();
        for (const document of target.documents) {
          const tokens = analyzer.tokens(document.body);
          if (!document.embeddings) throw new Error(`document ${document.id} has no embeddings`);
          hybrid.add({ id: document.id, tokens, embedding: document.embeddings });
        }
        return hybrid.commit(target.name);
      }
      default:
        throw new Error(`unsupported index type: ${target.type}`);
    }
  }
}

