  text: string;
  items?: string[];
  values?: number[];
}

export interface Theme {
  headingFont: string;
  bodyFont: string;
  accent: string;
}

export class SectionRenderer {
  constructor(private readonly theme: Theme) {}

  render(section: Section): string {
    switch (section.kind) {
      case 'heading': {
        const level = section.text.length > 40 ? 2 : 1;
        return `<h${level} style="font-family:${this.theme.headingFont}">${section.text}</h${level}>`;
      }
      case 'paragraph': {
        return `<p style="font-family:${this.theme.bodyFont}">${section.text}</p>`;
      }
      case 'list': {
        const items = (section.items ?? []).map((item) => `<li>${item}</li>`).join('');
        return `<ul style="font-family:${this.theme.bodyFont}">${items}</ul>`;
      }
      case 'bar-chart': {
        const values = section.values ?? [];
        const max = Math.max(1, ...values);
        const bars = values
          .map((value, index) => `<rect x="${index * 12}" y="${100 - (value / max) * 100}" width="10" height="${(value / max) * 100}" fill="${this.theme.accent}" />`)
          .join('');
        return `<svg viewBox="0 0 ${Math.max(1, values.length) * 12} 100" role="img">${bars}</svg>`;
      }
      default:
        throw new Error(`unsupported section kind: ${section.kind}`);
    }
  }
}

