  rateFor(currency: string): number;
}

export function describeCharge(charge: Charge, rates: RateTable): string {
  const base = `${(charge.amountCents / 100).toFixed(2)} ${charge.currency}`;
  if (charge.kind === 'sale') {
    return `${base} charged for ${charge.reference}`;
  } else if (charge.kind === 'refund') {
    const rate = rates.rateFor(charge.currency);
    return `${base} refunded (adjusted ${(charge.amountCents * rate).toFixed(0)})`;
  } else if (charge.kind === 'dispute') {
    const rate = rates.rateFor(charge.currency);
    const deadline = charge.deadline ?? 'unknown';
    return `${base} disputed at ${rate.toFixed(3)} until ${deadline}`;
  }
  throw new Error(`unsupported charge kind: ${charge.kind}`);
}

