    return `${head}s:${encodeURIComponent(envelope.payload)}`;
  } else if (typeof envelope.payload === 'number') {
    return `${head}n:${envelope.payload.toFixed(6)}`;
  } else if (typeof envelope.payload === 'boolean') {
    return `${head}b:${envelope.payload ? '1' : '0'}`;
  }
  throw new Error(`unsupported payload for ${envelope.id}`);
}

export function deserializePayload(raw: string): Envelope {
  const [id, createdAt, rest] = raw.split('|');
  const kind = rest!.slice(0, 1);
  const body = rest!.slice(2);
  const payload = kind === 's' ? decodeURIComponent(body) : kind === 'b' ? body === '1' : Number(body);
  return {
    id: id!,
    createdAt: createdAt!,
    payload,
  };
