import { verifyStripeSignature } from './stripe';
import { verifyPaypalSignature } from './paypal';
import { verifySquareSignature } from './square';

export interface IncomingWebhook {
  connectorName: string;
  headers: Record<string, string>;
  rawBody: string;
}

export interface EventBus {
  publish(topic: string, event: { type: string; data: unknown }): Promise<void>;
}

export class WebhookRouter {
  constructor(private readonly bus: EventBus, private readonly secret: string) {}

  async route(webhook: IncomingWebhook): Promise<void> {
    const name = webhook.connectorName;
    if (name === 'stripe') {
      if (!verifyStripeSignature(webhook.rawBody, webhook.headers, this.secret)) {
        throw new Error('invalid stripe signature');
      }
      const body = JSON.parse(webhook.rawBody) as { type: string; data: unknown };
      await this.bus.publish('billing.stripe', { type: body.type, data: body.data });
    } else if (name === 'paypal') {
      if (!verifyPaypalSignature(webhook.rawBody, webhook.headers, this.secret)) {
        throw new Error('invalid paypal signature');
      }
      const body = JSON.parse(webhook.rawBody) as { event_type: string; resource: unknown };
      await this.bus.publish('billing.paypal', { type: body.event_type, data: body.resource });
    } else if (name === 'square') {
      if (!verifySquareSignature(webhook.rawBody, webhook.headers, this.secret)) {
        throw new Error('invalid square signature');
      }
      const body = JSON.parse(webhook.rawBody) as { type: string; data: { object: unknown } };
      await this.bus.publish('billing.square', { type: body.type, data: body.data.object });
    } else {
      throw new Error(`unknown connector: ${name}`);
    }
  }
}

