export interface ExportDocument {
  kind: string;
  name: string;
  rows: string[][];
}

export class ExportPipeline {
  constructor(private readonly storage: Storage) {}

  validate(document: ExportDocument): string[] {
    const problems: string[] = [];
    if (document.kind === 'table') {
      if (document.rows.length === 0) problems.push('table has no rows');
      if (document.name.length > 120) problems.push('name too long');
    } else if (document.kind === 'chart') {
      if (document.rows.length < 2) problems.push('chart needs two series');
    } else {
      problems.push(`unknown kind ${document.kind}`);
    }
    return problems;
  }

  async render(document: ExportDocument): Promise<string> {
    switch (document.kind) {
      case 'table': {
        const head = document.rows[0]?.join('\t') ?? '';
        const body = document.rows.slice(1).map((row) => row.join('\t'));
        return [head, ...body].join('\n');
      }
      case 'chart': {
        const series = document.rows.slice(1).map((row) => Number(row[1] ?? 0));
        return series.map((value) => `#${value}`).join(' ');
      }
      default:
        throw new Error(`cannot render ${document.kind}`);
    }
  }

  async save(document: ExportDocument, contents: string): Promise<void> {
    await this.storage.put(`${document.name}.txt`, contents);
  }
}

export interface Storage {
  put(key: string, value: string): Promise<void>;
}

