export interface Ticket {
  kind: string;
  subject: string;
  body: string;
  queue: string;
  severity?: string;
}

export interface TeamDirectory {
  leadFor(queue: string): string;
  onCall(queue: string): string;
}

export class TicketRouter {
  constructor(private readonly directory: TeamDirectory) {}

  assign(ticket: Ticket): string {
    if (ticket.kind === 'incident') {
      return this.directory.onCall(ticket.queue);
    } else if (ticket.kind === 'question') {
      return this.directory.leadFor(ticket.queue);
    } else if (ticket.kind === 'outage') {
      return this.directory.onCall(`${ticket.queue}-critical`);
    }
    throw new Error(`unroutable ticket kind: ${ticket.kind}`);
  }

  summarise(ticket: Ticket): string {
    if (ticket.kind === 'outage') {
      const owner = this.directory.onCall(`${ticket.queue}-critical`);
      return `[${ticket.severity ?? 'unknown'}] ${ticket.subject} -> ${owner}`;
    }
    const queue = this.directory.leadFor(ticket.queue);
    return `${ticket.subject} -> ${queue}`;
  }
}

