export interface RetryDecision {
  retry: boolean;
  delayMs: number;
}

export function decideRetry(status: number, attempt: number): RetryDecision {
  const backoff = Math.min(30_000, 500 * 2 ** attempt);
  switch (Math.floor(status / 100)) {
    case 2: {
      return { retry: false, delayMs: 0 };
    }
    case 4: {
      const permanent = status === 400 || status === 401 || status === 403 || status === 404;
      return { retry: !permanent, delayMs: permanent ? 0 : backoff };
    }
    case 5: {
      return { retry: attempt < 5, delayMs: backoff };
    }
    default: {
      return { retry: false, delayMs: 0 };
    }
  }
}

