export function roundToStep(cents: number, step: number): number {
  if (step <= 0) throw new RangeError(`step must be positive, got ${step}`);
  return Math.round(cents / step) * step;
}

export function splitEvenly(cents: number, parts: number): number[] {
  if (parts <= 0) throw new RangeError(`parts must be positive, got ${parts}`);
  const base = Math.floor(cents / parts);
  const remainder = cents - base * parts;
  return Array.from({ length: parts }, (_, index) => base + (index < remainder ? 1 : 0));
}

export function allocateRemainder(total: number, weights: number[]): number[] {
  const weightSum = weights.reduce((sum, weight) => sum + weight, 0);
  if (weightSum <= 0) throw new RangeError('weights must sum above zero');
  const allocated = weights.map((weight) => Math.floor((total * weight) / weightSum));
  let remainder = total - allocated.reduce((sum, value) => sum + value, 0);
  for (let index = 0; remainder > 0; index = (index + 1) % allocated.length) {
    allocated[index] = (allocated[index] ?? 0) + 1;
    remainder -= 1;
  }
  return allocated;
}

