const PLUS_TAG = /\+[^@]*/;

export function normaliseEmail(raw: string): string {
  const trimmed = raw.trim().toLowerCase();
  const [, local = '', domain = ''] = trimmed.split('@');
  if (domain === '') throw new TypeError(`email is missing a domain: ${raw}`);
  return `${local.replace(PLUS_TAG, '')}@${domain}`;
}

export function domainOf(raw: string): string {
  const parts = raw.trim().toLowerCase().split('@');
  return parts[1] ?? '';
}

export function groupByDomain(emails: string[]): Map<string, string[]> {
  const groups = new Map<string, string[]>();
  for (const email of emails) {
    const domain = domainOf(email);
    const bucket = groups.get(domain) ?? [];
    bucket.push(normaliseEmail(email));
    groups.set(domain, bucket);
  }
  return groups;
}

