export type Listener<T> = (payload: T) => void;

export class Emitter<Events extends Record<string, unknown>> {
  private readonly listeners = new Map<keyof Events, Listener<never>[]>();

  on<K extends keyof Events>(topic: K, listener: Listener<Events[K]>): void {
    const bucket = this.listeners.get(topic) ?? [];
    bucket.push(listener as Listener<never>);
    this.listeners.set(topic, bucket);
  }

  count(topic: keyof Events): number {
    return this.listeners.get(topic)?.length ?? 0;
  }

  emit<K extends keyof Events>(topic: K, payload: Events[K]): void {
    const bucket = this.listeners.get(topic);
    if (!bucket) return;
    for (const listener of bucket) {
      (listener as Listener<Events[K]>)(payload);
    }
  }
}

after:
export type Listener<T> = (payload: T) => void;

export class Emitter<Events extends Record<string, unknown>> {
  private readonly listeners = new Map<keyof Events, Listener<never>[]>();

  on<K extends keyof Events>(topic: K, listener: Listener<Events[K]>): void {
    const bucket = this.listeners.get(topic) ?? [];
    bucket.push(listener as Listener<never>);
    this.listeners.set(topic, bucket);
  }

  count(topic: keyof Events): number {
    return this.listeners.get(topic)?.length ?? 0;
  }

  emit<K extends keyof Events>(topic: K, payload: Events[K]): void {
    const bucket = this.listeners.get(topic);
    if (!bucket) return;
    for (const listener of bucket) {
      if (typeof listener === 'function') {
        (listener as Listener<Events[K]>)(payload);
      }
    }
  }

  clear(topic: keyof Events): void {
    this.listeners.delete(topic);
  }
}

before:
export type Cell = string | number | null;

export interface SortSpec {
  column: number;
  descending: boolean;
}

export function sortSpecFor(column: number, descending = false): SortSpec {
  return { column, descending };
}

export function columnLabels(count: number): string[] {
  return Array.from({ length: count }, (_, index) => `Column ${index + 1}`);
}

export function sortRows(rows: Cell[][], spec: SortSpec): Cell[][] {
  const direction = spec.descending ? -1 : 1;
  return [...rows].sort((left, right) => {
    const a = left[spec.column] ?? null;
    const b = right[spec.column] ?? null;
    if (a === null && b === null) return 0;
    if (a === null) return 1;
    if (b === null) return -1;
    return a < b ? -direction : a > b ? direction : 0;
  });
}

after:
export type Cell = string | number | null;

export interface SortSpec {
  column: number;
  descending: boolean;
}

export function sortSpecFor(column: number, descending = false): SortSpec {
  return { column, descending };
}

export function columnLabels(count: number): string[] {
  return Array.from({ length: count }, (_, index) => `Column ${index + 1}`);
}

export function sortRows(rows: Cell[][], spec: SortSpec): Cell[][] {
  const direction = spec.descending ? -1 : 1;
  return [...rows].sort((left, right) => {
    const a = left[spec.column] ?? null;
    const b = right[spec.column] ?? null;
    if (a === null && b === null) return 0;
    if (a === null) return 1;
    if (b === null) return -1;
    if (typeof a === 'number' && typeof b === 'number') return (a - b) * direction;
    return String(a) < String(b) ? -direction : String(a) > String(b) ? direction : 0;
  });
}
